def solve():
    data = input().split()
    if not data:
        return

    iterator = iter(data)
    try:
        N = int(next(iterator))
    except StopIteration:
        return

    last_pos = {}
    min_len = float('inf')

    for i in range(N):
        try:
            val = int(next(iterator))
        except StopIteration:
            break

        if val in last_pos:
            length = i - last_pos[val] + 1
            if length < min_len:
                min_len = length
        last_pos[val] = i

    if min_len == float('inf'):
        print(-1)
    else:
        print(min_len)

