class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        step = 1
        m = len(grid)
        n = len(grid[0])

        for r in range(m):
            if r % 2 == 0:
                # Even row index (0, 2, ...): Traverse right
                # Iterate from column 0 to n-1
                for c in range(n):
                    # Keep cells at odd step positions (1st, 3rd, 5th...)
                    if step % 2 != 0:
                        result.append(grid[r][c])
                    step += 1
            else:
                # Odd row index (1, 3, ...): Traverse left
                # Iterate from column n-1 down to 0
                for c in range(n - 1, -1, -1):
                    # Keep cells at odd step positions (1st, 3rd, 5th...)
                    if step % 2 != 0:
                        result.append(grid[r][c])
                    step += 1
        return result

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # dp[c_u][c_v] stores the minimum cost to paint the houses up to the current pair
        # such that the current pair (u, v) has colors c_u and c_v respectively.
        # u is the index in the first half (0 to n/2 - 1)
        # v is the index in the second half (n - 1 to n/2)
        # Initially, we set up the state for the first pair of houses (0 and n-1).

        dp = [[float('inf')] * 3 for _ in range(3)]

        # Initialize for the first pair (houses 0 and n-1)
        for c_u in range(3):
            for c_v in range(3):
                if c_u != c_v:
                    dp[c_u][c_v] = cost[0][c_u] + cost[n-1][c_v]

        # Iterate through the remaining pairs.
        # We process pairs k from 1 to n/2 - 1.
        # Pair k consists of houses k and n-1-k.
        # The previous pair was k-1, consisting of houses k-1 and n-k.
        # Constraints between pairs:
        # 1. Adjacency: house k and k-1 must have different colors (c_u != c_prev_u)
        # 2. Adjacency: house n-1-k and n-k must have different colors (c_v != c_prev_v)
        # 3. Equidistant: house k and n-1-k must have different colors (c_u != c_v) - already checked in initialization and transition

        for k in range(1, n // 2):
            new_dp = [[float('inf')] * 3 for _ in range(3)]
            for c_u in range(3):
                for c_v in range(3):
                    # Constraint: Current pair houses must have different colors
                    if c_u == c_v:
                        continue

                    # Find the minimum cost from the previous pair
                    min_prev = float('inf')
                    for prev_c_u in range(3):
                        for prev_c_v in range(3):
                            # Constraint: Previous pair houses must have different colors
                            # (This was already enforced in the previous iteration)
                            if prev_c_u == prev_c_v:
                                continue

                            # Constraint: Adjacency between current and previous houses
                            # House k (c_u) and House k-1 (prev_c_u) must be different
                            if prev_c_u == c_u:
                                continue

                            # House n-1-k (c_v) and House n-k (prev_c_v) must be different
                            if prev_c_v == c_v:
                                continue

                            if dp[prev_c_u][prev_c_v] < min_prev:
                                min_prev = dp[prev_c_u][prev_c_v]

                    if min_prev != float('inf'):
                        new_dp[c_u][c_v] = min_prev + cost[k][c_u] + cost[n-1-k][c_v]

            dp = new_dp

        # The result is the minimum cost among all valid colorings for the last pair
        return min(min(row) for row in dp)

class Solution:
    def countPartitions(self, nums: List[int]) -> int:
        n = len(nums)
        total_sum = sum(nums)

        # If the total sum is even, the difference between left and right sums is always even.
        # There are n - 1 possible partitions.
        if total_sum % 2 == 0:
            return n - 1
        else:
            # If the total sum is odd, the difference is always odd.
            return 0

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        max_diff = 0

        # Iterate over all possible values v that could be added to make elements equal to k.
        # The range is small (1 to 50).
        for v in range(1, 51):
            if v == k:
                continue

            current_sum = 0
            local_max = 0

            for x in nums:
                if x == v:
                    current_sum += 1
                elif x == k:
                    current_sum -= 1
                # else 0

                if current_sum > local_max:
                    local_max = current_sum
                if current_sum < 0:
                    current_sum = 0

            if local_max > 0:
                max_diff = max(max_diff, local_max)

        return total_k + max_diff

class Solution:
    def maxDifference(self, s: str) -> int:
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1

        odd_frequencies = []
        even_frequencies = []

        for count in freq.values():
            if count % 2 == 1:
                odd_frequencies.append(count)
            else:
                even_frequencies.append(count)

        return max(odd_frequencies) - min(even_frequencies)

