class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Map each unique element value to its first occurrence index.
        # We only store the first occurrence of each value to satisfy the "smallest index j" rule.
        val_to_index = {}
        for i, e in enumerate(elements):
            if e not in val_to_index:
                val_to_index[e] = i

        assigned = []

        # Optimization: If 1 is in elements, it divides every group size.
        # Since elements are processed in order, 1 will be at index 0.
        # Thus, if 1 is in elements, all groups can be assigned index 0.
        if 1 in val_to_index:
            return [0] * len(groups)

        # Iterate through each group to find the best element index.
        for g in groups:
            best_idx = -1

            # Find all divisors of g.
            # We iterate from 1 to sqrt(g). For each i, i and g//i are divisors.
            limit = int(g**0.5)

            # We iterate through potential divisors to find the one with the smallest index.
            # We check both divisors i and g // i.
            for i in range(1, limit + 1):
                if g % i == 0:
                    # Check the first divisor i
                    if i in val_to_index:
                        idx = val_to_index[i]
                        if best_idx == -1 or idx < best_idx:
                            best_idx = idx
                        if best_idx == 0:
                            break # 0 is the smallest possible index, so we can stop.

                    # Check the second divisor g // i
                    if i != (g // i):
                        if (g // i) in val_to_index:
                            idx = val_to_index[g // i]
                            if best_idx == -1 or idx < best_idx:
                                best_idx = idx
                                if best_idx == 0:
                                    break

            assigned.append(best_idx)

        return assigned

