class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        # Dictionary to store the count of each number across all subarrays
        count_map = defaultdict(int)
        n = len(nums)

        # Iterate through each subarray of size k
        # There are (n - k + 1) such subarrays
        for i in range(n - k + 1):
            # Iterate through the elements in the current subarray
            # The elements are nums[i], nums[i+1], ..., nums[i+k-1]
            for j in range(k):
                count_map[nums[i + j]] += 1

        # Find the largest number that appears in exactly one subarray
        result = -1
        for num, count in count_map.items():
            if count == 1:
                if num > result:
                    result = num

        return result

