class Solution:
    def findMaxSum(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        n = len(nums1)

        # Create a mapping from nums1 values to their indices
        value_to_indices = {}
        for i in range(n):
            if nums1[i] not in value_to_indices:
                value_to_indices[nums1[i]] = []
            value_to_indices[nums1[i]].append(i)

        # Sort the unique values in nums1 for efficient iteration
        sorted_values = sorted(value_to_indices.keys())

        answer = []

        for i in range(n):
            current_val = nums1[i]

            # Collect all indices j where nums1[j] < current_val
            relevant_indices = []
            for val in sorted_values:
                if val < current_val:
                    relevant_indices.extend(value_to_indices[val])
                else:
                    break

            if not relevant_indices:
                answer.append(0)
            else:
                # Select top k values from nums2 at these indices
                if len(relevant_indices) <= k:
                    answer.append(sum(nums2[j] for j in relevant_indices))
                else:
                    # Get nums2 values and select k largest
                    nums2_vals = [nums2[j] for j in relevant_indices]
                    nums2_vals.sort(reverse=True)
                    answer.append(sum(nums2_vals[:k]))

        return answer

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        # Track which baskets are used
        used = [False] * n

        # For each fruit, find the leftmost available basket with capacity >= fruit quantity
        for i in range(n):
            fruit_quantity = fruits[i]
            placed = False
            # Linear scan to find the first available basket
            for j in range(n):
                if not used[j] and baskets[j] >= fruit_quantity:
                    used[j] = True
                    placed = True
                    break

            if not placed:
                return i + 1  # Return the count of unplaced fruits

        return 0

class Solution:
    def maxSum(self, nums: List[int]) -> int:
        unique_elements = set(nums)
        max_sum = sum(x for x in unique_elements if x > 0)

        if max_sum == 0:
            if 0 in unique_elements:
                return 0
            else:
