class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        pos_map = {}
        for i, num in enumerate(nums):
            if num not in pos_map:
                pos_map[num] = []
            pos_map[num].append(i)

        ans_map = {}
        for val, indices in pos_map.items():
            if len(indices) == 1:
                ans_map[indices[0]] = -1
            else:
                k = len(indices)
                for i in range(k):
                    curr_idx = indices[i]
                    prev_idx = indices[(i - 1) % k]
                    next_idx = indices[(i + 1) % k]

                    if i > 0:
                        dist_prev = curr_idx - prev_idx
                    else:
                        dist_prev = n - prev_idx + curr_idx

                    if i < k - 1:
                        dist_next = next_idx - curr_idx
                    else:
                        dist_next = n - curr_idx + next_idx

                    ans_map[curr_idx] = min(dist_prev, dist_next)

        return [ans_map[q] for q in queries]

