class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        # Check if the array is already a zero array initially
        if all(x == 0 for x in nums):
            return 0

        # Iterate through each query in the list
        # We need to find the minimum k such that after processing the first k queries,
        # the array becomes a zero array.
        # Since n is small (<= 10) and m is up to 1000, we can simulate the process.

        for k, (l, r, val) in enumerate(queries, start=1):
            # Apply the current query: decrement values in range [l, r] by val
            for i in range(l, r + 1):
                nums[i] -= val

            # Check if the array has become a zero array
            if all(x == 0 for x in nums):
                return k

            # If any element becomes negative, it can never be restored to 0 
            # because we only decrement values. Thus, it's impossible.
            if any(x < 0 for x in nums):
                return -1

        # If we process all queries and the array is never a zero array
        return -1

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # The deck is an n x n grid, so the total number of available cells is n * n.
        # Each container weighs w.
        # The maximum number of containers we can load is limited by two factors:
        # 1. The number of cells available (n * n).
        # 2. The ship's weight capacity (maxWeight // w).

        total_cells = n * n
        max_by_weight = maxWeight // w

        return min(total_cells, max_by_weight)

