class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Build adjacency list
        graph = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct integers common to both properties[i] and properties[j]
                common = set(properties[i]) & set(properties[j])
                if len(common) >= k:
                    graph[i].append(j)
                    graph[j].append(i)

        # Count connected components using BFS
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                # BFS to visit all nodes in this component
                queue = [i]
                visited[i] = True
                while queue:
                    node = queue.pop(0)
                    for neighbor in graph[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)

        return components

