class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        n = len(nums)
        max_diff = 0
        # Iterate through each element to compare with its adjacent element in the circular array
        for i in range(n):
            # The next element for index i is (i + 1) % n to handle the circular wrap-around
            diff = abs(nums[i] - nums[(i + 1) % n])
            if diff > max_diff:
                max_diff = diff
        return max_diff

