class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        distinct_numbers = set()
        # Iterate through all permutations of length 3 from the given digits
        for p in permutations(digits, 3):
            # Check if the first digit is not 0 (no leading zeros)
            # Check if the last digit is even
            if p[0] != 0 and p[2] % 2 == 0:
                # Construct the 3-digit number and add to set to ensure distinctness
                # Since digits are single digits (0-9), we can calculate the value directly
                num = p[0] * 100 + p[1] * 10 + p[2]
                distinct_numbers.add(num)
        return len(distinct_numbers)
